mapper.select:
SELECT u.id AS resident_id, u.username, u.display_name, u.status AS resident_status, m.id AS meter_id, m.meter_no, m.meter_name, m.meter_type, m.display_type, m.unit, m.status AS meter_status, rm.created_by, rm.created_at AS bound_at FROM resident_meter AS rm INNER JOIN sys_user AS u ON u.id = rm.resident_id INNER JOIN meter AS m ON m.id = rm.meter_id WHERE m.deleted = 0
AND rm.resident_id = #{residentId}
AND rm.meter_id = #{meterId}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%') OR m.meter_no LIKE CONCAT('%', #{keyword}, '%') OR m.meter_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY rm.created_at DESC, rm.resident_id DESC, rm.meter_id DESC

SELECT u.id AS resident_id, u.username, u.display_name, u.status, rm.created_at AS bound_at FROM resident_meter AS rm INNER JOIN sys_user AS u ON u.id = rm.resident_id WHERE rm.meter_id = #{meterId}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY rm.created_at DESC, rm.resident_id DESC
